function _v1SelectGuidanceSource(m, candidates, prof, dt){
    const cfg = _v1SourceArbiterConfig(prof);
    const step = clamp(Number.isFinite(dt) ? dt : 0, 0, 0.25);
    const nowLife = Number.isFinite(m?.life) ? m.life : 0;
