        profileKey: prof?.seekerType ?? 'SARH',
        current:null, sourceAgeS:0,
        candidate:null, candidateAgeS:0,
        belowHoldAgeS:0,
        switchCount:0,
        lastSwitchFrom:'NONE', lastSwitchTo:'NONE', lastSwitchReason:'INIT',
        lastGoodState:null, lastGoodLife:nowLife
