    const own=samNavB1OwnState(m),mVx=own.velMps.x,mVy=own.velMps.y,mVz=own.velMps.z;
    const vH = Math.hypot(mVx, mVy);
    const vTot = Math.max(60, Math.hypot(vH, mVz));
